static double valueAt(const QString &name,int position)
{
 if(name.startsWith("ModelRotation"))return position;
 if(name.startsWith("ModelOffset"))return position/100.;
 // Independent decade table,not the production sliderScale implementation.
 const std::array<double,7> decade{{.0001,.001,.01,.1,1,10,100}};
 const int band=position/90;return decade[band]*(10+position-90*band);
}
